-- Generated by scripts/cloud_run.py sql from src/congestion/athena.py. Do not edit.
UNLOAD (
WITH raw AS (
    SELECT
        month,
        CAST(pickup_datetime AS timestamp)              AS pickup,
        CAST(dropoff_datetime AS timestamp)             AS dropoff,
        CAST(request_datetime AS timestamp)             AS request,
        CAST(PULocationID AS integer)                   AS pu_zone,
        CAST(DOLocationID AS integer)                   AS do_zone,
        CAST(base_passenger_fare AS double)             AS fare,
        CAST(coalesce(tips, 0) AS double)               AS tips,
        CAST(driver_pay AS double)                      AS driver_pay,
        CAST(trip_miles AS double)                      AS miles,
        CAST(coalesce(cbd_congestion_fee, 0) AS double) AS fee,
        (shared_request_flag = 'Y')                     AS shared_req,
        (shared_match_flag = 'Y')                       AS shared_match
    FROM tlc.raw_hvfhv
), clean AS (
    SELECT *,
           date_diff('second', pickup, dropoff) / 6e1 AS minutes,
           CASE WHEN request IS NOT NULL AND date_diff('second', request, pickup) BETWEEN 0 AND 3600
                THEN date_diff('second', request, pickup) / 6e1 END AS wait_min
    FROM raw
    WHERE pickup >= date_parse(month, '%Y-%m') AND pickup < date_add('month', 1, date_parse(month, '%Y-%m'))
      AND date_diff('second', pickup, dropoff) BETWEEN 60 AND 4 * 3600
      AND miles >= 0 AND miles <= 100
      AND (fare IS NULL OR fare >= 0)
)
SELECT 'hvfhv' AS service, CAST(pickup AS date) AS date, hour(pickup) AS hour,
       CASE WHEN pu_zone IS NULL OR pu_zone NOT BETWEEN 1 AND 263 THEN 'unknown' WHEN pu_zone IN (4, 12, 13, 45, 48, 50, 68, 79, 87, 88, 90, 100, 107, 113, 114, 125, 137, 144, 148, 158, 161, 162, 163, 164, 170, 186, 209, 211, 224, 229, 230, 231, 232, 233, 234, 246, 249, 261) THEN 'cbd' WHEN pu_zone IN (43, 140, 141, 142, 143, 237) THEN 'border' WHEN pu_zone IN (1, 132, 138) THEN 'airport' WHEN pu_zone IN (4, 12, 13, 24, 41, 42, 43, 45, 48, 50, 68, 74, 75, 79, 87, 88, 90, 100, 103, 104, 105, 107, 113, 114, 116, 120, 125, 127, 128, 137, 140, 141, 142, 143, 144, 148, 151, 152, 153, 158, 161, 162, 163, 164, 166, 170, 186, 194, 202, 209, 211, 224, 229, 230, 231, 232, 233, 234, 236, 237, 238, 239, 243, 244, 246, 249, 261, 262, 263) THEN 'manhattan_north' ELSE 'outer' END AS pu_group,
       count(*)                                          AS trips,
       count(*) FILTER (WHERE do_zone IN (4, 12, 13, 45, 48, 50, 68, 79, 87, 88, 90, 100, 107, 113, 114, 125, 137, 144, 148, 158, 161, 162, 163, 164, 170, 186, 209, 211, 224, 229, 230, 231, 232, 233, 234, 246, 249, 261)) AS trips_to_cbd,
       count(*) FILTER (WHERE fee > 0)                   AS fee_trips,
       sum(fare)                                         AS fare_sum,
       sum(driver_pay)                                   AS driver_pay_sum,
       sum(miles)                                        AS miles_sum,
       sum(minutes)                                      AS minutes_sum
FROM clean
GROUP BY 1, 2, 3, 4
)
TO 's3://<your-bucket>/out/group_hour/service=hvfhv/'
WITH (format = 'PARQUET', compression = 'SNAPPY');
